namespace
{

void addf(std::string& log, const char* fmt, ...)
{
    char buf[1024];
    va_list ap; va_start(ap, fmt);
    vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    log += buf; log += "\r\n";
}

constexpr unsigned kMaxVerts = 32768;

} // namespace

std::string FrontendUi::init(ID3D12Device* device, ID3D12CommandQueue* queue,
                             IDXGISwapChain1* swap1, bool* ok)
{
    std::string log;
    *ok = false;
    m_ok = false;
    m_device = device; m_queue = queue;
    HRESULT hr = swap1->QueryInterface(IID_PPV_ARGS(&m_swap));
    addf(log, "FRONTEND-UI SwapChain As IDXGISwapChain3: %s hr=0x%08lX", SUCCEEDED(hr) ? "PASS" : "FAIL", (unsigned long)hr);
    if (FAILED(hr)) return log;
    DXGI_SWAP_CHAIN_DESC1 desc{};
    hr = m_swap->GetDesc1(&desc);
    if (FAILED(hr)) { addf(log, "FRONTEND-UI GetDesc1 FAIL hr=0x%08lX", (unsigned long)hr); return log; }
    m_width = desc.Width; m_height = desc.Height; m_bufferCount = desc.BufferCount;
    addf(log, "FRONTEND-UI swapchain %ux%u buffers=%u", m_width, m_height, m_bufferCount);
    if (m_bufferCount == 0 || m_bufferCount > 8) { addf(log, "FRONTEND-UI bufferCount out of range"); return log; }
    D3D12_DESCRIPTOR_HEAP_DESC hd{};
    hd.Type = D3D12_DESCRIPTOR_HEAP_TYPE_RTV; hd.NumDescriptors = m_bufferCount;
    hr = m_device->CreateDescriptorHeap(&hd, IID_PPV_ARGS(&m_rtv));
    if (FAILED(hr)) { addf(log, "FRONTEND-UI RTV heap FAIL hr=0x%08lX", (unsigned long)hr); return log; }
    m_rtvSize = m_device->GetDescriptorHandleIncrementSize(D3D12_DESCRIPTOR_HEAP_TYPE_RTV);
    m_back.resize(m_bufferCount);
    auto h = m_rtv->GetCPUDescriptorHandleForHeapStart();
    for (unsigned i = 0; i < m_bufferCount; ++i)
    {
        hr = m_swap->GetBuffer(i, IID_PPV_ARGS(&m_back[i]));
        if (FAILED(hr)) { addf(log, "FRONTEND-UI GetBuffer[%u] FAIL hr=0x%08lX", i, (unsigned long)hr); return log; }
        m_device->CreateRenderTargetView(m_back[i].Get(), nullptr, h);
        h.ptr += m_rtvSize;
    }
    // Root signature: one SRV table (t0) + static linear sampler (s0).
    D3D12_DESCRIPTOR_RANGE range{};
    range.RangeType = D3D12_DESCRIPTOR_RANGE_TYPE_SRV;
    range.NumDescriptors = 1;
    D3D12_ROOT_PARAMETER param{};
    param.ParameterType = D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
    param.ShaderVisibility = D3D12_SHADER_VISIBILITY_PIXEL;
    param.DescriptorTable.NumDescriptorRanges = 1;
    param.DescriptorTable.pDescriptorRanges = &range;
    D3D12_STATIC_SAMPLER_DESC samp{};
    samp.Filter = D3D12_FILTER_MIN_MAG_MIP_LINEAR;
    samp.AddressU = samp.AddressV = samp.AddressW = D3D12_TEXTURE_ADDRESS_MODE_CLAMP;
    samp.ShaderVisibility = D3D12_SHADER_VISIBILITY_PIXEL;
    D3D12_ROOT_SIGNATURE_DESC rsDesc{};
    rsDesc.NumParameters = 1;
    rsDesc.pParameters = &param;
    rsDesc.NumStaticSamplers = 1;
    rsDesc.pStaticSamplers = &samp;
    rsDesc.Flags = D3D12_ROOT_SIGNATURE_FLAG_ALLOW_INPUT_ASSEMBLER_INPUT_LAYOUT;
    ComPtr<ID3DBlob> rsBlob, rsErr;
    hr = D3D12SerializeRootSignature(&rsDesc, D3D_ROOT_SIGNATURE_VERSION_1, &rsBlob, &rsErr);
    if (FAILED(hr)) { addf(log, "FRONTEND-UI SerializeRootSignature FAIL hr=0x%08lX", (unsigned long)hr); return log; }
    hr = m_device->CreateRootSignature(0, rsBlob->GetBufferPointer(), rsBlob->GetBufferSize(), IID_PPV_ARGS(&m_rs));
    if (FAILED(hr)) { addf(log, "FRONTEND-UI CreateRootSignature FAIL hr=0x%08lX", (unsigned long)hr); return log; }
    // PSO: build-time dxc-signed UI shaders (embedded).
    D3D12_INPUT_ELEMENT_DESC il[] = {
        {"POSITION", 0, DXGI_FORMAT_R32G32_FLOAT, 0, 0, D3D12_INPUT_CLASSIFICATION_PER_VERTEX_DATA, 0},
        {"TEXCOORD", 0, DXGI_FORMAT_R32G32_FLOAT, 0, 8, D3D12_INPUT_CLASSIFICATION_PER_VERTEX_DATA, 0},
        {"COLOR", 0, DXGI_FORMAT_R32G32B32A32_FLOAT, 0, 16, D3D12_INPUT_CLASSIFICATION_PER_VERTEX_DATA, 0},
    };
    D3D12_GRAPHICS_PIPELINE_STATE_DESC pso{};
    pso.pRootSignature = m_rs.Get();
    pso.VS = {ui_vs_cso, ui_vs_cso_len};
    pso.PS = {ui_ps_cso, ui_ps_cso_len};
    pso.InputLayout = {il, 3};
    pso.PrimitiveTopologyType = D3D12_PRIMITIVE_TOPOLOGY_TYPE_TRIANGLE;
    pso.RasterizerState.FillMode = D3D12_FILL_MODE_SOLID;
    pso.RasterizerState.CullMode = D3D12_CULL_MODE_NONE;
    pso.RasterizerState.DepthClipEnable = TRUE;
    pso.DepthStencilState.DepthEnable = FALSE;
    pso.DepthStencilState.StencilEnable = FALSE;
    pso.SampleDesc.Count = 1;
    pso.SampleMask = UINT_MAX;
    pso.NumRenderTargets = 1;
    pso.RTVFormats[0] = DXGI_FORMAT_R8G8B8A8_UNORM;
    auto& bl = pso.BlendState.RenderTarget[0];
    bl.BlendEnable = TRUE;
    bl.SrcBlend = D3D12_BLEND_SRC_ALPHA;
    bl.DestBlend = D3D12_BLEND_INV_SRC_ALPHA;
    bl.BlendOp = D3D12_BLEND_OP_ADD;
    bl.SrcBlendAlpha = D3D12_BLEND_ONE;
    bl.DestBlendAlpha = D3D12_BLEND_INV_SRC_ALPHA;
    bl.BlendOpAlpha = D3D12_BLEND_OP_ADD;
    bl.RenderTargetWriteMask = D3D12_COLOR_WRITE_ENABLE_ALL;
    hr = m_device->CreateGraphicsPipelineState(&pso, IID_PPV_ARGS(&m_pso));
    addf(log, "FRONTEND-UI-PSO signed ui_vs(%u B)+ui_ps(%u B): %s hr=0x%08lX",
         ui_vs_cso_len, ui_ps_cso_len, SUCCEEDED(hr) ? "PASS" : "FAIL", (unsigned long)hr);
    if (FAILED(hr)) return log;
    // Command objects + fence (PresentLoop discipline).
    hr = m_device->CreateCommandAllocator(D3D12_COMMAND_LIST_TYPE_DIRECT, IID_PPV_ARGS(&m_alloc));
    if (FAILED(hr)) { addf(log, "FRONTEND-UI alloc FAIL hr=0x%08lX", (unsigned long)hr); return log; }
    hr = m_device->CreateCommandList(0, D3D12_COMMAND_LIST_TYPE_DIRECT, m_alloc.Get(), nullptr, IID_PPV_ARGS(&m_list));
    if (FAILED(hr)) { addf(log, "FRONTEND-UI list FAIL hr=0x%08lX", (unsigned long)hr); return log; }
    hr = m_device->CreateFence(0, D3D12_FENCE_FLAG_NONE, IID_PPV_ARGS(&m_fence));
    if (FAILED(hr)) { addf(log, "FRONTEND-UI fence FAIL hr=0x%08lX", (unsigned long)hr); return log; }
    m_fenceEv = CreateEventExW(nullptr, nullptr, 0, EVENT_ALL_ACCESS);
    if (!m_fenceEv) { addf(log, "FRONTEND-UI fence event FAIL"); return log; }
    // Vertex buffer: upload heap, rewritten every frame (fence-serialised).
    {
        D3D12_HEAP_PROPERTIES hp{};
        hp.Type = D3D12_HEAP_TYPE_UPLOAD;
        D3D12_RESOURCE_DESC rd{};
        rd.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER;
        rd.Width = static_cast<UINT64>(kMaxVerts) * sizeof(Vert);
        rd.Height = 1; rd.DepthOrArraySize = 1; rd.MipLevels = 1;
        rd.SampleDesc.Count = 1;
        rd.Layout = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;
        hr = m_device->CreateCommittedResource(&hp, D3D12_HEAP_FLAG_NONE, &rd,
                                               D3D12_RESOURCE_STATE_GENERIC_READ,
                                               nullptr, IID_PPV_ARGS(&m_vb));
        if (FAILED(hr)) { addf(log, "FRONTEND-UI vb FAIL hr=0x%08lX", (unsigned long)hr); return log; }
    }
    // Font atlas texture (pre-baked R8, uploaded once).
    {
        D3D12_HEAP_PROPERTIES dh{};
        dh.Type = D3D12_HEAP_TYPE_DEFAULT;
        D3D12_RESOURCE_DESC td{};
        td.Dimension = D3D12_RESOURCE_DIMENSION_TEXTURE2D;
        td.Width = kFontAtlasW; td.Height = kFontAtlasH;
        td.DepthOrArraySize = 1; td.MipLevels = 1;
        td.Format = DXGI_FORMAT_R8_UNORM;
        td.SampleDesc.Count = 1;
        hr = m_device->CreateCommittedResource(&dh, D3D12_HEAP_FLAG_NONE, &td,
                                               D3D12_RESOURCE_STATE_COPY_DEST,
                                               nullptr, IID_PPV_ARGS(&m_fontTex));
        if (FAILED(hr)) { addf(log, "FRONTEND-UI font tex FAIL hr=0x%08lX", (unsigned long)hr); return log; }
        ComPtr<ID3D12Resource> up;
        D3D12_HEAP_PROPERTIES uh{};
        uh.Type = D3D12_HEAP_TYPE_UPLOAD;
        const UINT64 rowPitch = (static_cast<UINT64>(kFontAtlasW) + D3D12_TEXTURE_DATA_PITCH_ALIGNMENT - 1)
                                & ~(static_cast<UINT64>(D3D12_TEXTURE_DATA_PITCH_ALIGNMENT) - 1);
        D3D12_RESOURCE_DESC ud{};
        ud.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER;
        ud.Width = rowPitch * kFontAtlasH;
        ud.Height = 1; ud.DepthOrArraySize = 1; ud.MipLevels = 1;
        ud.SampleDesc.Count = 1;
        ud.Layout = D3D12_TEXTURE_LAYOUT_ROW_MAJOR;
        hr = m_device->CreateCommittedResource(&uh, D3D12_HEAP_FLAG_NONE, &ud,
                                               D3D12_RESOURCE_STATE_GENERIC_READ,
                                               nullptr, IID_PPV_ARGS(&up));
        if (FAILED(hr)) { addf(log, "FRONTEND-UI font upload FAIL hr=0x%08lX", (unsigned long)hr); return log; }
        void* mapped = nullptr;
        D3D12_RANGE noRead{0, 0};
        hr = up->Map(0, &noRead, &mapped);
        if (FAILED(hr) || !mapped) { addf(log, "FRONTEND-UI font map FAIL hr=0x%08lX", (unsigned long)hr); return log; }
        for (unsigned y = 0; y < kFontAtlasH; ++y)
            memcpy(static_cast<unsigned char*>(mapped) + y * rowPitch,
                   kFontAtlas + static_cast<size_t>(y) * kFontAtlasW, kFontAtlasW);
        up->Unmap(0, nullptr);
        D3D12_TEXTURE_COPY_LOCATION dst{}, src{};
        dst.pResource = m_fontTex.Get();
        dst.Type = D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;
        dst.SubresourceIndex = 0;
        src.pResource = up.Get();
        src.Type = D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;
        src.PlacedFootprint.Footprint.Format = DXGI_FORMAT_R8_UNORM;
        src.PlacedFootprint.Footprint.Width = kFontAtlasW;
        src.PlacedFootprint.Footprint.Height = kFontAtlasH;
        src.PlacedFootprint.Footprint.Depth = 1;
        src.PlacedFootprint.Footprint.RowPitch = static_cast<UINT>(rowPitch);
        m_list->CopyTextureRegion(&dst, 0, 0, 0, &src, nullptr);
        D3D12_RESOURCE_BARRIER bar{};
        bar.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
        bar.Transition.pResource = m_fontTex.Get();
        bar.Transition.StateBefore = D3D12_RESOURCE_STATE_COPY_DEST;
        bar.Transition.StateAfter = D3D12_RESOURCE_STATE_PIXEL_SHADER_RESOURCE;
        bar.Transition.Subresource = D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
        m_list->ResourceBarrier(1, &bar);
        hr = m_list->Close();
        if (FAILED(hr)) { addf(log, "FRONTEND-UI font list close FAIL hr=0x%08lX", (unsigned long)hr); return log; }
        ID3D12CommandList* lists[] = {m_list.Get()};
        m_queue->ExecuteCommandLists(1, lists);
        const unsigned long long fv = ++m_fv;
        m_queue->Signal(m_fence.Get(), fv);
        if (m_fence->GetCompletedValue() < fv)
        {
            m_fence->SetEventOnCompletion(fv, m_fenceEv);
            WaitForSingleObjectEx(m_fenceEv, INFINITE, FALSE);
        }
    }
    // SRV heap (shader-visible, 1 descriptor).
    D3D12_DESCRIPTOR_HEAP_DESC sd{};
    sd.Type = D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV;
    sd.NumDescriptors = 1;
    sd.Flags = D3D12_DESCRIPTOR_HEAP_FLAG_SHADER_VISIBLE;
    hr = m_device->CreateDescriptorHeap(&sd, IID_PPV_ARGS(&m_srv));
    if (FAILED(hr)) { addf(log, "FRONTEND-UI srv heap FAIL hr=0x%08lX", (unsigned long)hr); return log; }
    D3D12_SHADER_RESOURCE_VIEW_DESC sv{};
    sv.Format = DXGI_FORMAT_R8_UNORM;
    sv.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
    sv.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
    sv.Texture2D.MipLevels = 1;
    m_device->CreateShaderResourceView(m_fontTex.Get(), &sv,
                                       m_srv->GetCPUDescriptorHandleForHeapStart());
    m_verts.reserve(kMaxVerts);
    m_ok = true;
    *ok = true;
    addf(log, "FRONTEND-UI-INIT PASS atlas=%ux%u cell=%ux%u", kFontAtlasW, kFontAtlasH, kFontCellW, kFontCellH);
    return log;
}

void FrontendUi::to_ndc(float px, float py, float& nx, float& ny) const
{
    nx = m_width ? (px / static_cast<float>(m_width)) * 2.0f - 1.0f : 0.0f;
    ny = m_height ? 1.0f - (py / static_cast<float>(m_height)) * 2.0f : 0.0f;
}

void FrontendUi::push_quad(float x, float y, float w, float h,
                           float u0, float v0, float u1, float v1, UiColor c)
{
    if (m_verts.size() + 6 > kMaxVerts) return;
    float x0, y0, x1, y1;
    to_ndc(x, y, x0, y0);
    to_ndc(x + w, y + h, x1, y1);
    const Vert tl{x0, y0, u0, v0, c.r, c.g, c.b, c.a};
    const Vert tr{x1, y0, u1, v0, c.r, c.g, c.b, c.a};
    const Vert bl{x0, y1, u0, v1, c.r, c.g, c.b, c.a};
    const Vert br{x1, y1, u1, v1, c.r, c.g, c.b, c.a};
    m_verts.push_back(tl); m_verts.push_back(tr); m_verts.push_back(bl);
    m_verts.push_back(tr); m_verts.push_back(br); m_verts.push_back(bl);
}

void FrontendUi::begin_frame(float r, float g, float b)
{
    m_verts.clear();
    m_clear[0] = r; m_clear[1] = g; m_clear[2] = b; m_clear[3] = 1.0f;
}

void FrontendUi::quad(float x, float y, float w, float h, UiColor c)
{
    // Cell (0,0) is baked solid white; sample its center.
    const float uc = (kFontCellW * 0.5f) / static_cast<float>(kFontAtlasW);
    const float vc = (kFontCellH * 0.5f) / static_cast<float>(kFontAtlasH);
    push_quad(x, y, w, h, uc, vc, uc, vc, c);
}

float FrontendUi::text_width(float scale, const std::string& s) const
{
    float w = 0.0f;
    for (unsigned char ch : s)
        w += static_cast<float>(kFontWidths[ch]) * scale;
    return w;
}

void FrontendUi::text(float x, float y, float scale, UiColor c, const std::string& s)
{
    float cx = x;
    const float cw = static_cast<float>(kFontCellW) * scale;
    const float chh = static_cast<float>(kFontCellH) * scale;
    for (unsigned char ch : s)
    {
        if (ch < 32 || ch > 126) ch = '?';
        const unsigned col = ch % kFontCols;
        const unsigned row = ch / kFontCols;
        const float u0 = static_cast<float>(col * kFontCellW) / static_cast<float>(kFontAtlasW);
        const float v0 = static_cast<float>(row * kFontCellH) / static_cast<float>(kFontAtlasH);
        const float u1 = static_cast<float>((col + 1) * kFontCellW) / static_cast<float>(kFontAtlasW);
        const float v1 = static_cast<float>((row + 1) * kFontCellH) / static_cast<float>(kFontAtlasH);
        push_quad(cx, y, cw, chh, u0, v0, u1, v1, c);
        cx += static_cast<float>(kFontWidths[ch]) * scale;
    }
}

void FrontendUi::progress_bar(float x, float y, float w, float h, int percent,
                              UiColor back, UiColor fill)
{
    quad(x, y, w, h, back);
    if (percent >= 0)
    {
        if (percent > 100) percent = 100;
        quad(x + 2, y + 2, (w - 4) * (percent / 100.0f), h - 4, fill);
    }
}

HRESULT FrontendUi::present_frame()
{
    if (!m_ok) return E_FAIL;
    const unsigned idx = m_swap->GetCurrentBackBufferIndex();
    m_alloc->Reset();
    m_list->Reset(m_alloc.Get(), m_pso.Get());
    D3D12_RESOURCE_BARRIER bar{};
    bar.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
    bar.Transition.pResource = m_back[idx].Get();
    bar.Transition.StateBefore = D3D12_RESOURCE_STATE_PRESENT;
    bar.Transition.StateAfter = D3D12_RESOURCE_STATE_RENDER_TARGET;
    bar.Transition.Subresource = D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
    m_list->ResourceBarrier(1, &bar);
    auto hh = m_rtv->GetCPUDescriptorHandleForHeapStart();
    hh.ptr += static_cast<size_t>(idx) * m_rtvSize;
    m_list->ClearRenderTargetView(hh, m_clear, 0, nullptr);
    if (!m_verts.empty())
    {
        void* mapped = nullptr;
        D3D12_RANGE noRead{0, 0};
        if (SUCCEEDED(m_vb->Map(0, &noRead, &mapped)) && mapped)
        {
            memcpy(mapped, m_verts.data(), m_verts.size() * sizeof(Vert));
            m_vb->Unmap(0, nullptr);
        }
        m_list->OMSetRenderTargets(1, &hh, FALSE, nullptr);
        D3D12_VIEWPORT vp{0.0f, 0.0f, static_cast<float>(m_width),
                          static_cast<float>(m_height), 0.0f, 1.0f};
        D3D12_RECT sc{0, 0, static_cast<LONG>(m_width), static_cast<LONG>(m_height)};
        m_list->RSSetViewports(1, &vp);
        m_list->RSSetScissorRects(1, &sc);
        m_list->SetGraphicsRootSignature(m_rs.Get());
        ID3D12DescriptorHeap* heaps[] = {m_srv.Get()};
        m_list->SetDescriptorHeaps(1, heaps);
        m_list->SetGraphicsRootDescriptorTable(0, m_srv->GetGPUDescriptorHandleForHeapStart());
        D3D12_VERTEX_BUFFER_VIEW vbv{};
        vbv.BufferLocation = m_vb->GetGPUVirtualAddress();
        vbv.SizeInBytes = static_cast<UINT>(m_verts.size() * sizeof(Vert));
        vbv.StrideInBytes = sizeof(Vert);
        m_list->IASetVertexBuffers(0, 1, &vbv);
        m_list->IASetPrimitiveTopology(D3D_PRIMITIVE_TOPOLOGY_TRIANGLELIST);
        m_list->DrawInstanced(static_cast<UINT>(m_verts.size()), 1, 0, 0);
    }
    bar.Transition.StateBefore = D3D12_RESOURCE_STATE_RENDER_TARGET;
    bar.Transition.StateAfter = D3D12_RESOURCE_STATE_PRESENT;
    m_list->ResourceBarrier(1, &bar);
    HRESULT hr = m_list->Close();
    if (FAILED(hr)) return hr;
    ID3D12CommandList* lists[] = {m_list.Get()};
    m_queue->ExecuteCommandLists(1, lists);
    hr = m_swap->Present(1, 0);
    if (SUCCEEDED(hr)) ++m_presented;
    const unsigned long long fv = ++m_fv;
    m_queue->Signal(m_fence.Get(), fv);
    if (m_fence->GetCompletedValue() < fv)
    {
        m_fence->SetEventOnCompletion(fv, m_fenceEv);
        WaitForSingleObjectEx(m_fenceEv, INFINITE, FALSE);
    }
    return hr;
}

// ---- screens state machine (pure logic) ----

UiEvent ui_apply_input(UiState& st, const MenuInput& in, int entry_count)
{
    if (st.screen == Screen::Loading || st.screen == Screen::Compiling || st.screen == Screen::Stopping) return UiEvent::None;
    if (st.screen == Screen::Library)
    {
        if (entry_count > 0)
        {
            if (in.down) st.selected = (st.selected + 1) % entry_count;
            if (in.up) st.selected = (st.selected + entry_count - 1) % entry_count;
            if (in.right) st.selected = std::min(entry_count - 1, st.selected + 10);
            if (in.left) st.selected = std::max(0, st.selected - 10);
            if (in.accept)
            {
                st.screen = Screen::Actions;
                st.action = 0;
                st.status.clear();
                return UiEvent::None;
            }
        }
        else
        {
            st.selected = 0;
        }
        if (in.menu) return UiEvent::RescanRequested;
        return UiEvent::None;
    }
    // DeleteConfirm (1.1.3): A confirms (host deletes), B backs out
    // to Actions. Navigation input is ignored here - no accidental
    // selection drift while a destructive confirm is on screen.
    if (st.screen == Screen::DeleteConfirm)
    {
        if (in.back)
        {
            st.screen = Screen::Actions;
            st.status.clear();
            return UiEvent::None;
        }
        if (in.accept) return UiEvent::DeleteConfirmed;
        return UiEvent::None;
    }
    // Actions
    if (in.down) st.action = (st.action + 1) % 3;
    if (in.up) st.action = (st.action + 2) % 3;
    if (in.back)
    {
        st.screen = Screen::Library;
        st.status.clear();
        return UiEvent::None;
    }
    if (in.accept)
    {
        if (st.action == 0) return UiEvent::LoadSelected;
        if (st.action == 1) return UiEvent::CompileSelected;
        if (st.action == 2)
        {
            st.screen = Screen::DeleteConfirm;
            st.status.clear();
            return UiEvent::DeleteSelected;
        }
    }
    return UiEvent::None;
}

